import React from 'react';
import PropTypes from 'prop-types';
import 'react-responsive-carousel/lib/styles/carousel.min.css';
import { Carousel } from 'react-responsive-carousel';

const { PUBLIC_URL } = process.env;

const PrintablesCarousel = ({ carouselItems }) => (
  <div>
    <Carousel>
      {carouselItems.map((item) => {
        const src = /^(https?:)?\/\//i.test(item.src) ? item.src : `${PUBLIC_URL}${item.src}`;
        return (
          <div key={`${item.src}`}>
            <img src={src} alt={item?.alt} />
            {item.legend && item.legend.trim() !== '' && (
              <p className='legend'>{item.legend}</p>
            )}
          </div>
        );
      })}
    </Carousel>
  </div>
);
PrintablesCarousel.propTypes = {
  carouselItems: PropTypes.arrayOf(
    PropTypes.shape({
      src: PropTypes.string.isRequired,
      alt: PropTypes.string,
      legend: PropTypes.string,
    }),
  ).isRequired,
};

export default PrintablesCarousel;
