import React from 'react';
import { useParams } from 'react-router-dom';
import Main from '../layouts/Main';
import products from '../data/products.json';
import PrintablesCarousel from './PrintablesCarousel';
import './ProductPage.css';

const ProductPage = () => {
  const { id } = useParams();
  const product = products.find(p => String(p.id) === String(id));

  if (!product) {
    return (
      <Main title='Product Not Found'>
        <div className='product-page'><h2>Product not found</h2></div>
      </Main>
    );
  }

  return (
    <Main title={product.title} description={product.description}>
      <div className='product-page'>
        <button className='back-btn' onClick={() => window.history.back()} style={{ marginBottom: '1em' }}>Back</button>
        <h2>{product.title}</h2>
        <div className='product-details'>
          <div className='product-carousel'>
            <PrintablesCarousel carouselItems={product.images
              ? product.images.map(img => ({ src: img })) : [{ src: product.image }]}
            />
          </div>
          <div className='product-info'>
            <p>{product.description}</p>
            {product.info && (
              <p className='product-info-extra'>{product.info}</p>
            )}
            {/* Add more product details here if needed */}
            <button
              className='contact-btn'
              style={{ marginTop: '2em' }}
              onClick={() => {
                const subject = 'Product Inquiry';
                const body = `I am interested in the product: ${product.title}`;
                const mailtoLink = `mailto:ofir@ofiryaron.com?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`;
                window.location.href = mailtoLink;
              }}
            >
              Contact Me
            </button>
          </div>
        </div>
      </div>
    </Main>
  );
};

export default ProductPage;
